useQuery<ManagedAdminList, Error>(["admin-management", page, search, billingFilter, statusFilter], () => {
    const params = new URLSearchParams({
        offset: String(page * PAGE_SIZE),
        limit: String(PAGE_SIZE),
        username: search,
    });
    if (billingFilter)
        params.set("billing_mode", billingFilter);
    if (statusFilter)
        params.set("account_status", statusFilter);
    return fetch(`/admin-management?${params.toString()}`);
}, { keepPreviousData: true, enabled: canManage, refetchInterval: 15000 })

